function loadPartial(e,t){return fetch(e).then(function(t){if(!t.ok)throw new Error("Failed to load partial: "+e);return t.text()}).then(function(e){var n=document.getElementById(t);n&&(n.innerHTML=e)})}function setActiveNavLink(){var e=window.location.pathname.split("/").pop()||"index.html";document.querySelectorAll("#header-placeholder .nav-link").forEach(function(t){t.getAttribute("href")===e&&t.classList.add("active")})}function loadHeaderFooter(){Promise.all([loadPartial("assets/includes/header.html","header-placeholder").then(setActiveNavLink),loadPartial("assets/includes/footer.html","footer-placeholder")]).then(function(){window.dispatchEvent(new Event("header-footer-loaded"))}).catch(function(e){console.error(e)})}document.addEventListener("DOMContentLoaded",loadHeaderFooter);